#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, int>>> g(n);
    for (int i = 0; i < m; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        --a;
        --b;
        g[a].push_back({b, c});
        g[b].push_back({a, c});
    }

    const long long INF = 4000000000000000000LL;
    vector<long long> d(n, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> q;
    d[0] = 0;
    q.push({0, 0});

    while (!q.empty()) {
        auto [x, u] = q.top();
        q.pop();
        if (x != d[u]) continue;
        for (auto [v, w] : g[u]) {
            if (d[v] > x + w) {
                d[v] = x + w;
                q.push({d[v], v});
            }
        }
    }

    cout << (d[n - 1] == INF ? -1 : d[n - 1]) << endl;
    return 0;
}
